/// 整数列a, bの畳み込みを、定義どおりの二重ループで計算する。
///
/// c[k] = Σ a[i] * b[j]（i + j = kとなるすべての組）
///
/// - 時間計算量: O(NM)、出力用の領域: O(N + M)。
/// - どちらかが空なら空のVecを返す。それ以外の長さはN + M - 1。
/// - 積と加算途中の値を含む、すべての整数演算がi64の範囲内であること。
/// - modは取らない。高速なNTT版を作る際の、小さな入力用の検証基準にも使う。
pub fn convolution_naive_i64(a: &[i64], b: &[i64]) -> Vec<i64> {
    returnif!(a.is_empty() || b.is_empty(), vec![]);

    let mut c = vec![0_i64; a.len() + b.len() - 1];
    for i in 0..a.len() {
        for j in 0..b.len() {
            c[i + j] += a[i] * b[j]
        }
    }
    return c;
} // end of method

