/// 係数列から、評価点ω^0, ..., ω^(N-1)での値を求める。
/// この順変換では、角度の符号をプラスに統一する。
#[inline(always)]
pub fn fft(a: &mut Vec<Complex64>) -> Vec<Complex64> {
    returnif!(a.is_empty(), vec![]);
    returnif!(a.len() == 1, vec![a[0]]);

    let mut n = 1;
    while n < a.len() {
        n <<= 1;
    }
    a.resize(n, Complex64::new(0.0, 0.0));

    return fft_recursive(a, false);
} // end of fft

/// 逆変換, FFTが返した評価値を受け取る
#[inline(always)]
pub fn ifft(values: &[Complex64]) -> Vec<Complex64> {
    returnif!(values.is_empty(), vec![]);
    assert!(values.len().is_power_of_two(), "評価値の個数は2のべき乗にしてねー(´・ω・｀)");

    let mut a = fft_recursive(values, true);

    // 再帰が終わった後に、変換長Nで1回割る
    let n = values.len() as f64;
    for value in &mut a {
        *value /= n;
    }

    return a;
} // end of ifft

/// 順変換・逆変換共通の再帰
/// 入力長は1以上の2のべき乗
#[inline(always)]
fn fft_recursive(a: &[Complex64], inverse: bool) -> Vec<Complex64> {
    let n = a.len();
    returnif!(n == 1, vec![a[0]]);

    // A(x) = E(x^2) + xO(x^2) に分割
    let mut even: Vec<Complex64> = a.iter().step_by(2).copied().collect();
    let mut odd: Vec<Complex64> = a.iter().skip(1).step_by(2).copied().collect();

    // 子の長さはN/2
    // 子が作る根の角度は親の2倍
    let even_values = fft_recursive(&even, inverse);
    let odd_values = fft_recursive(&odd, inverse);

    // 逆変換では回転方向を反転
    let direction = if inverse { -1.0 } else { 1.0 };
    let omega = Complex64::from_polar(1.0, direction * TAU / n as f64);
    let mut w = Complex64::new(1.0, 0.0);
    let mut values = vec![Complex64::new(0.0, 0.0); n];

    for k in 0..(n / 2) {
        let t = w * odd_values[k];
        values[k] = even_values[k] + t;
        values[k + n / 2] = even_values[k] - t;
        w *= omega;
    }

    return values;
} // end of fft_recursive

/// 実数列の畳み込み, 結果には浮動小数点の丸め誤差を含む
#[inline(always)]
pub fn convolution_fft(a: &[f64], b: &[f64]) -> Vec<f64> {
    returnif!(a.is_empty() || b.is_empty(), vec![]);

    let result_len = a.len() + b.len() - 1;
    let mut n = 1;
    while n < result_len {
        n <<= 1;
    }

    // 積の係数が全部収まる共通の変換長に
    let mut left: Vec<Complex64> = a.iter().map(|&x| Complex64::new(x, 0.0)).collect();
    let mut right: Vec<Complex64> = b.iter().map(|&x| Complex64::new(x, 0.0)).collect();
    left.resize(n, Complex64::new(0.0, 0.0));
    right.resize(n, Complex64::new(0.0, 0.0));

    let mut left_values = fft(&mut left);
    let mut right_values = fft(&mut right);

    // 同じ評価点での値同士をかける
    for k in 0..n {
        left_values[k] *= right_values[k];
    }

    let coefficients = ifft(&left_values);
    return coefficients.iter().take(result_len).map(|z| z.re).collect();
} // end of convolution_fft

