const NTT_MOD: u64 = 998244353_u64;
const NTT_PRIMITIVE_ROOT: u64 = 3;

/// base^exp mod NTT_MOD を繰り返し二乗法で
#[inline(always)]
fn ntt_pow(mut base: u64, mut exp: u64) -> u64 {
    base %= NTT_MOD;
    let mut result = 1;

    while exp > 0 {
        if (exp & 1) == 1 {
            result = (result * base) % NTT_MOD;
        }
        base = (base * base) % NTT_MOD;
        exp >>= 1;
    }
    return result;
} // end of method

/// 長さnの変換で使う、1の原始n乗根
#[inline(always)]
fn ntt_root(n: usize) -> u64 {
    assert!(
        n.is_power_of_two() && n <= (1_usize << 23),
        "変換長は1以上2^23以下の2のべき乗にしてねー(´・ω・｀)"
    );

    return ntt_pow(NTT_PRIMITIVE_ROOT, (NTT_MOD - 1) / n as u64);
} // end of method

/// 入力はmodを取り、2のべき乗の長さまでゼロパディング
#[inline(always)]
pub fn ntt(a: &mut Vec<u64>) -> Vec<u64> {
    returnif!(a.is_empty(), vec![]);
    assert!(a.len() <= (1_usize << 23), "変換長は2^23以下にしてねー(´・ω・｀)");

    let mut n = 1;
    while n < a.len() {
        n <<= 1;
    }

    for value in a.iter_mut() {
        *value %= NTT_MOD;
    }
    a.resize(n, 0);

    return ntt_recursive(a, false);
}

/// 入力長は1以上の2のべき乗、各要素はNTT_MOD未満。
#[inline(always)]
fn ntt_recursive(a: &[u64], inverse: bool) -> Vec<u64> {
    let n = a.len();
    returnif!(n == 1, vec![a[0]]);

    let even: Vec<u64> = a.iter().step_by(2).copied().collect();
    let odd: Vec<u64> = a.iter().skip(1).step_by(2).copied().collect();

    let even_values = ntt_recursive(&even, inverse);
    let odd_values = ntt_recursive(&odd, inverse);

    let omega = if inverse { ntt_inv(ntt_root(n)) } else { ntt_root(n) };
    let mut w = 1;
    let mut values = vec![0; n];

    for k in 0..(n / 2) {
        let t = (w * odd_values[k]) % NTT_MOD;

        // u64で負にならないように、法を足してから
        values[k] = (even_values[k] + t) % NTT_MOD;
        values[k + n / 2] = (even_values[k] + NTT_MOD - t) % NTT_MOD;

        w = (w * omega) % NTT_MOD;
    }
    return values;
} // end of method

/// mod NTT_MODでの逆元, xは0以外のあまり
#[inline(always)]
fn ntt_inv(x: u64) -> u64 {
    let x = x % NTT_MOD;
    assert_ne!(x, 0, "0には逆元がないよー(´・ω・｀)");
    return ntt_pow(x, NTT_MOD - 2);
} // end of ntt_inv

/// 評価値列から係数列を復元
#[inline(always)]
pub fn intt(values: &[u64]) -> Vec<u64> {
    returnif!(values.is_empty(), vec![]);
    assert!(
        values.len().is_power_of_two() && values.len() <= (1_usize << 23),
        "評価値の個数は1以上2^23以下の2のべき乗にしてねー(´・ω・｀)"
    );

    let normalized: Vec<u64> = values.iter().map(|&x| x % NTT_MOD).collect();
    let mut a = ntt_recursive(&normalized, true);

    // Nで割る代わりにNの逆元をかける
    let inv_n = ntt_inv(values.len() as u64);
    for value in &mut a {
        *value = (*value * inv_n) % NTT_MOD;
    }

    return a;
} // end of method

/// 畳み込みを mod 998244353(NTT_MOD) で
/// 結果の長さは a.len() + b.len() - 1, 片方が空なら空配列
pub fn convolution_ntt(a: &[u64], b: &[u64]) -> Vec<u64> {
    returnif!(a.is_empty() || b.is_empty(), vec![]);

    let result_len = a.len() + b.len() - 1;
    assert!(
        result_len <= (1_usize << 23),
        "畳み込み結果の長さは2^23以下にしてねー(´・ω・｀)"
    );

    let mut n = 1;
    while n < result_len {
        n <<= 1;
    }

    // 同じ評価点で計算するために共通の長さに
    let mut left = a.to_vec();
    let mut right = b.to_vec();
    left.resize(n, 0);
    right.resize(n, 0);

    let mut left_values = ntt(&mut left);
    let mut right_values = ntt(&mut right);

    // C(ω^k) = A(ω^k) * B(ω^k)
    for k in 0..n {
        left_values[k] = (left_values[k] * right_values[k]) % NTT_MOD;
    }

    let mut c = intt(&left_values);
    c.truncate(result_len);
    return c;
} // end of convolution_ntt

