// 畳み込み（998244353・反復型radix-4）
// 参考: AtCoder Library convolution.hpp (CC0)
// https://github.com/atcoder/ac-library/blob/master/atcoder/convolution.hpp
//
// 既存のntt/inttとは内部の評価値の順序が異なるため、
// このモジュール内の順変換・逆変換を組み合わせて使用する。
//
// 入力: 任意のu64。結果長は2^23以下。
// 出力: mod 998244353の係数列。片方が空なら空配列。
// 計算量: O(L log L)、領域: O(L)。Lは結果長以上の最小の2のべき乗。
// 片方が16要素以下ならO(n*m)の愚直法へ切り替える。
pub fn convolution_ntt_fast(a: &[u64], b: &[u64]) -> Vec<u64> {
    ntt_fast_impl::convolution(a, b)
}

mod ntt_fast_impl {

    const P: u32 = 998_244_353;
    const MAX_LEN: usize = 1 << 23;

    #[inline(always)]
    fn add(a: u32, b: u32) -> u32 {
        let x = a + b;
        if x >= P { x - P } else { x }
    }

    #[inline(always)]
    fn sub(a: u32, b: u32) -> u32 {
        if a >= b { a - b } else { a + P - b }
    }

    #[inline(always)]
    fn mul(a: u32, b: u32) -> u32 {
        (a as u64 * b as u64 % P as u64) as u32
    }

    fn pow(mut a: u32, mut e: u32) -> u32 {
        let mut r = 1;
        while e > 0 {
            if e & 1 != 0 {
                r = mul(r, a);
            }
            a = mul(a, a);
            e >>= 1;
        }
        r
    }

    struct Info {
        root: [u32; 24],
        iroot: [u32; 24],
        rate2: [u32; 22],
        irate2: [u32; 22],
        rate3: [u32; 21],
        irate3: [u32; 21],
    }

    impl Info {
        fn new() -> Self {
            let mut info = Self {
                root: [0; 24],
                iroot: [0; 24],
                rate2: [0; 22],
                irate2: [0; 22],
                rate3: [0; 21],
                irate3: [0; 21],
            };
            info.root[23] = pow(3, (P - 1) >> 23);
            info.iroot[23] = pow(info.root[23], P - 2);
            for i in (0..23).rev() {
                info.root[i] = mul(info.root[i + 1], info.root[i + 1]);
                info.iroot[i] = mul(info.iroot[i + 1], info.iroot[i + 1]);
            }
            let (mut prod, mut iprod) = (1, 1);
            for i in 0..22 {
                info.rate2[i] = mul(info.root[i + 2], prod);
                info.irate2[i] = mul(info.iroot[i + 2], iprod);
                prod = mul(prod, info.iroot[i + 2]);
                iprod = mul(iprod, info.root[i + 2]);
            }
            let (mut prod, mut iprod) = (1, 1);
            for i in 0..21 {
                info.rate3[i] = mul(info.root[i + 3], prod);
                info.irate3[i] = mul(info.iroot[i + 3], iprod);
                prod = mul(prod, info.iroot[i + 3]);
                iprod = mul(iprod, info.root[i + 3]);
            }
            info
        }
    }

    // ACLと同じ段構成。評価値の並びは通常のNTTと異なるため、
    // 必ずこのforwardとinverseを組み合わせる。
    fn forward(a: &mut [u32], info: &Info) {
        let h = a.len().trailing_zeros() as usize;
        let mut len = 0;
        while len < h {
            if h - len == 1 {
                let p = 1 << (h - len - 1);
                let groups = 1 << len;
                let mut rot = 1;
                for (s, block) in a.chunks_exact_mut(2 * p).enumerate() {
                    let (left, right) = block.split_at_mut(p);
                    for (l, r) in left.iter_mut().zip(right.iter_mut()) {
                        let x = *l;
                        let y = mul(*r, rot);
                        *l = add(x, y);
                        *r = sub(x, y);
                    }
                    if s + 1 < groups {
                        rot = mul(rot, info.rate2[s.trailing_ones() as usize]);
                    }
                }
                len += 1;
            } else {
                let p = 1 << (h - len - 2);
                let groups = 1 << len;
                let mut rot = 1;
                let imag = info.root[2];
                for (s, block) in a.chunks_exact_mut(4 * p).enumerate() {
                    let rot2 = mul(rot, rot);
                    let rot3 = mul(rot2, rot);
                    let (a0, rest) = block.split_at_mut(p);
                    let (a1, rest) = rest.split_at_mut(p);
                    let (a2, a3) = rest.split_at_mut(p);
                    for (((v0, v1), v2), v3) in a0.iter_mut().zip(a1).zip(a2).zip(a3) {
                        let x0 = *v0;
                        let x1 = mul(*v1, rot);
                        let x2 = mul(*v2, rot2);
                        let x3 = mul(*v3, rot3);
                        let t0 = add(x0, x2);
                        let t1 = add(x1, x3);
                        let t2 = sub(x0, x2);
                        let t3 = mul(sub(x1, x3), imag);
                        *v0 = add(t0, t1);
                        *v1 = sub(t0, t1);
                        *v2 = add(t2, t3);
                        *v3 = sub(t2, t3);
                    }
                    if s + 1 < groups {
                        rot = mul(rot, info.rate3[s.trailing_ones() as usize]);
                    }
                }
                len += 2;
            }
        }
    }

    fn inverse(a: &mut [u32], info: &Info) {
        let h = a.len().trailing_zeros() as usize;
        let mut len = h;
        while len > 0 {
            if len == 1 {
                let p = 1 << (h - len);
                let groups = 1 << (len - 1);
                let mut rot = 1;
                for (s, block) in a.chunks_exact_mut(2 * p).enumerate() {
                    let (left, right) = block.split_at_mut(p);
                    for (l, r) in left.iter_mut().zip(right.iter_mut()) {
                        let x = *l;
                        let y = *r;
                        *l = add(x, y);
                        *r = mul(sub(x, y), rot);
                    }
                    if s + 1 < groups {
                        rot = mul(rot, info.irate2[s.trailing_ones() as usize]);
                    }
                }
                len -= 1;
            } else {
                let p = 1 << (h - len);
                let groups = 1 << (len - 2);
                let mut rot = 1;
                let imag = info.iroot[2];
                for (s, block) in a.chunks_exact_mut(4 * p).enumerate() {
                    let rot2 = mul(rot, rot);
                    let rot3 = mul(rot2, rot);
                    let (a0, rest) = block.split_at_mut(p);
                    let (a1, rest) = rest.split_at_mut(p);
                    let (a2, a3) = rest.split_at_mut(p);
                    for (((v0, v1), v2), v3) in a0.iter_mut().zip(a1).zip(a2).zip(a3) {
                        let x0 = *v0;
                        let x1 = *v1;
                        let x2 = *v2;
                        let x3 = *v3;
                        let t0 = add(x0, x1);
                        let t1 = sub(x0, x1);
                        let t2 = add(x2, x3);
                        let t3 = mul(sub(x2, x3), imag);
                        *v0 = add(t0, t2);
                        *v1 = mul(add(t1, t3), rot);
                        *v2 = mul(sub(t0, t2), rot2);
                        *v3 = mul(sub(t1, t3), rot3);
                    }
                    if s + 1 < groups {
                        rot = mul(rot, info.irate3[s.trailing_ones() as usize]);
                    }
                }
                len -= 2;
            }
        }
    }

    /// 入力は任意のu64。出力はmod 998244353の係数列。
    pub(super) fn convolution(a: &[u64], b: &[u64]) -> Vec<u64> {
        if a.is_empty() || b.is_empty() {
            return vec![];
        }
        // 各入力長も先に確認し、結果長の加算を安全な範囲に限定する。
        assert!(a.len() <= MAX_LEN && b.len() <= MAX_LEN, "入力長は2^23以下にしてください");
        let size = a.len() + b.len() - 1;
        assert!(size <= MAX_LEN, "畳み込み結果の長さは2^23以下にしてください");

        // 小さな片方に対しては、変換を行うより愚直法が軽い。
        if a.len().min(b.len()) <= 16 {
            let (short, long) = if a.len() <= b.len() { (a, b) } else { (b, a) };
            let short: Vec<u32> = short.iter().map(|&x| (x % P as u64) as u32).collect();
            let mut c = vec![0_u32; size];
            for (i, &x) in long.iter().enumerate() {
                let x = (x % P as u64) as u32;
                for (j, &y) in short.iter().enumerate() {
                    c[i + j] = add(c[i + j], mul(x, y));
                }
            }
            return c.into_iter().map(u64::from).collect();
        }
        let n = size.next_power_of_two();
        let mut left = vec![0_u32; n];
        let mut right = vec![0_u32; n];
        for (out, &x) in left.iter_mut().zip(a) {
            *out = (x % P as u64) as u32;
        }
        for (out, &x) in right.iter_mut().zip(b) {
            *out = (x % P as u64) as u32;
        }

        let info = Info::new();
        forward(&mut left, &info);
        forward(&mut right, &info);
        for (l, &r) in left.iter_mut().zip(&right) {
            *l = mul(*l, r);
        }
        inverse(&mut left, &info);

        // 必要な係数だけ正規化してu64へ戻す。
        let inv_n = pow(n as u32, P - 2);
        left.truncate(size);
        left.into_iter().map(|x| mul(x, inv_n) as u64).collect()
    }
}
